INSERT INTO wv_source_units (id, canonical_input, workspace_id, group_id, user_id, source_id, parent_unit_id, unit_type, title, order_index, start_ref, end_ref, anchor_text, summary, unit_json, meta_json) VALUES ('wv_unit_q12_1_7', 'wv_source_unit:quran:12:1-7', 'ws_quran', 'grp_tafsir', 1, 'wv_src_q12', 'wv_unit_q12', 'passage', 'Passage 1 (1-7)', 1, '12:1', '12:7', 'الر ... آيات للسائلين', 'Opening passage of Surah Yusuf covering revelation, Arabic Qur''an, best of stories, the dream, caution, election, ta''wil, and signs for seekers.', '{"surah":12,"ayah_from":1,"ayah_to":7,"passage_type":"opening","locatorLabel":"12:1-7","readingMinutes":7,"readingBody":["الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ ١","إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ ٢","نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ بِمَآ أَوۡحَيۡنَآ إِلَيۡكَ هَٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ لَمِنَ ٱلۡغَٰفِلِينَ ٣","إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ ٤","قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ٥","وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ ٦","۞ لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ ٧"]}', '{}') ON CONFLICT(id) DO UPDATE SET canonical_input = excluded.canonical_input, workspace_id = excluded.workspace_id, group_id = excluded.group_id, user_id = excluded.user_id, source_id = excluded.source_id, parent_unit_id = excluded.parent_unit_id, unit_type = excluded.unit_type, title = excluded.title, order_index = excluded.order_index, start_ref = excluded.start_ref, end_ref = excluded.end_ref, anchor_text = excluded.anchor_text, summary = excluded.summary, unit_json = excluded.unit_json, meta_json = excluded.meta_json, updated_at = datetime('now');
